data: {"index":1,"delta":{"text":" its core, the internet is a global network of interconnected computers communicating through a standardized set","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" of rules. To understand how a simple web page request travels across the world, we can trace the journey from physical hardware to the software","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" protocol that displays the content.\n\n### 1. The Physical Layer: Cables and Infrastructure\nEverything on the internet relies","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" on physical hardware. While Wi-Fi and 5G cellular networks connect our personal devices to local routers, those routers","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" are plugged into wired networks. \n\nDeep beneath our streets and oceans lie massive networks of fiber-optic cables. These cables contain","type":"text"},"event_type":"step.delta"}

