data: {"index":1,"delta":{"text":" continents, allowing data to travel at nearly the speed of light across the globe. \n\n### 2. Packets:","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" Breaking Data Down\nWhen you send a message, request an image, or load a video, the data isn't sent as one","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" massive continuous stream. Instead, the sending computer breaks the data down into small chunks called **packets**. \n\nEach packet contains","type":"text"},"event_type":"step.delta"}

