data: {"index":1,"delta":{"text":" a payload (a piece of the actual data) and a header (containing metadata such as the sender’s IP address, the destination","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" IP address, and the packet's sequence number). Breaking data into packets ensures that if one packet gets lost or corrupted","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":", only that specific piece needs to be resent, rather than the entire file.\n\n### 3. Addressing: IP and","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" DNS\nJust as postal mail needs a street address to reach its destination, every device connected to the internet has a unique numerical","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" identifier called an **IP address** (Internet Protocol address), such as `192.0.2.1`.","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" \n\nHowever, humans are terrible at remembering long strings of numbers. This is where the **Domain Name System (DNS)** comes in","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":". Think of DNS as the phonebook of the internet. When you type `example.com` into your web browser","type":"text"},"event_type":"step.delta"}

event: step.delta
