event: step.delta
data: {"index":1,"delta":{"text":"*   A **GET** request asks the server to retrieve a resource (like a webpage, image, or style sheet).\n*   A","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" **POST** request sends data to the server (like logging into an account or submitting a form).\n\nThe server processes this","type":"text"},"event_type":"step.delta"}

